void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    struct ftrace_event_file *file;
    struct ring_buffer *buffer;
    struct ring_buffer_event *event;
    struct syscall_exit_event *entry;

    int syscall_num = regs->ax;

    if (syscall_num < 0 || syscall_num >= __NR_syscalls)
        return;

    file = sys_trace_array->syscall_files[syscall_num];
    if (!file || !file->tracing_enabled)
        return;

    buffer = file->trace_buffer;
    event = ring_buffer_lock_reserve(buffer, sizeof(*entry));
    if (!event)
        return;

    entry = ring_buffer_event_data(event);
    entry->syscall_num = syscall_num;
    entry->return_value = ret;

    ring_buffer_unlock_commit(buffer, event);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret)
{
    int syscall_nr = (int)(regs->ax);
    struct ftrace_file *file;
    struct ring_buffer *buffer;
    struct ring_buffer_event *event;
    struct trace_entry *entry;

    if (syscall_nr < 0 || syscall_nr >= NR_syscalls)
        return;

    file = per_cpu_ptr(ftrace_array, smp_processor_id());
    if (!file || !file->tracing_on)
        return;

    buffer = file->buffer;
    event = ring_buffer_reserve(buffer, sizeof(*entry));
    if (!event)
        return;

    entry = ring_buffer_event_data(event);
    entry->type = TRACE_SYSCALL_EXIT;
    entry->pid = current->pid;
    entry->syscall = syscall_nr;
    entry->ret = ret;

    ring_buffer_commit(buffer, event);
}

void syscall_exit(void *data, struct pt_regs *regs, long ret) {
    struct ftrace_event *event;
    struct ring_buffer *buffer;
    struct ftrace_file *file;
    int syscall_nr;

    syscall_nr = (int)regs->ax;
    if (syscall_nr < 0 || syscall_nr >= MAX_SYSCALLS)
        return;

    file = syscalls[syscall_nr].file;
    if (!file || !file->tracing)
        return;

    buffer = file->buffer;
    event = ring_buffer_reserve(buffer, sizeof(struct syscall_event));
    if (!event)
        return;

    event->syscall_nr = syscall_nr;
    event->return_value = ret;

    ring_buffer_commit(buffer, event);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    int syscall;

    if (!user_mode(regs))
        return;

    syscall = (int)regs->ax;
    if (syscall >= __NR_syscalls)
        return;

    struct trace_array *tr = data;
    struct trace_array_cpu *tp_cpu = tr->data[raw_smp_processor_id()];
    struct ring_buffer *buffer = tp_cpu->trace_buffer.buffer;
    struct ring_buffer_event *event;
    unsigned long flags;
    struct ftrace_raw_syscall_exit *entry;

    if (ring_buffer_reserve(buffer, sizeof(*entry), &event, &flags) != 0)
        return;

    entry = ring_buffer_event_data(event);
    entry->syscall = syscall;
    entry->ret = ret;

    ring_buffer_commit(buffer, event, flags);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret) {
    struct trace_array *tr = data;
    struct trace_event_file *file;
    struct ring_buffer *buffer;
    struct ring_buffer_event *event;
    struct ftrace_event_call *call;
    unsigned int flags = 0;
    int syscall_nr;

    syscall_nr = (long)(regs->ax);

    if (syscall_nr < 0 || syscall_nr >= __NR_syscalls)
        return;

    call = trace_get_event_file(tr, syscalls, sys_exit, syscall_nr);
    if (!call)
        return;

    file = call->event_file;
    if (!file || !file->tracing_on)
        return;

    buffer = file->ring_buffer;
    if (!buffer)
        return;

    event = ring_buffer_lock_reserve(buffer, sizeof(struct syscall_exit_event), flags);
    if (!event)
        return;

    struct syscall_exit_event *entry = ring_buffer_event_data(event);
    entry->syscall_nr = syscall_nr;
    entry->ret = ret;

    ring_buffer_unlock_commit(buffer, event);
}
